class Solution {
  public int countPairs(int[] nums) {
    Map<Integer, Integer> seen = new HashMap<>();
    int answer = 0;
    for (int x : nums) {
      // numbers are padded to 7 digits so swaps may move leading zeros
      char[] d = new char[7];
      int v = x;
      for (int i = 6; i >= 0; i--) {
        d[i] = (char) ('0' + v % 10);
        v /= 10;
      }
      Set<Integer> reachable = new HashSet<>();
      reachable.add(x);
      for (int i = 0; i < 7; i++) {
        for (int j = i + 1; j < 7; j++) {
          swap(d, i, j);
          reachable.add(value(d));
          for (int a = 0; a < 7; a++) {
            for (int b = a + 1; b < 7; b++) {
              swap(d, a, b);
              reachable.add(value(d));
              swap(d, a, b);
            }
          }
          swap(d, i, j);
        }
      }
      for (int y : reachable) answer += seen.getOrDefault(y, 0);
      seen.merge(x, 1, Integer::sum);
    }
    return answer;
  }

  private void swap(char[] d, int i, int j) {
    char t = d[i];
    d[i] = d[j];
    d[j] = t;
  }

  private int value(char[] d) {
    int v = 0;
    for (char c : d) v = v * 10 + (c - '0');
    return v;
  }
}
